#!/usr/bin/env node
/**
 * db:ledger:snapshot
 *
 * Regenerates db/migrations/.ledger.json from the canonical production ledger
 * _system._schema_migrations, so verify:applied-migrations-immutable can see
 * every applied migration when it runs somewhere without database access (CI).
 *
 * The snapshot is a CACHE of the canonical ledger, never a second source of
 * truth. It exists only because GitHub Actions has no production credentials.
 *
 * BACKEND-PRE-DEPLOY-RED (2026-08-16): the previous snapshot was regenerated by
 * hand, rotted for a month (353 entries vs 877 files), and the guard reading it
 * reported OK the whole time. Refreshing is now (a) one command and (b) done
 * automatically by db-migrate.mjs after a successful apply, so the coder who
 * applies a migration commits the refreshed snapshot in the same PR.
 */
import fs from "node:fs";
import path from "node:path";

const CANONICAL_LEDGER_TABLE = "_system._schema_migrations";

export async function writeLedgerSnapshot({ client, ledgerPath, sourceLabel = "db:ledger:snapshot" }) {
  const { rows } = await client.query(
    `SELECT filename, checksum FROM ${CANONICAL_LEDGER_TABLE} ORDER BY filename ASC;`
  );
  const payload = {
    _comment:
      "GENERATED FILE - cache of the canonical ledger _system._schema_migrations, read by " +
      "verify:applied-migrations-immutable where the database is unreachable. Do not hand-edit. " +
      "Regenerate with: npm run db:ledger:snapshot",
    generated_by: sourceLabel,
    migration_count: rows.length,
    migrations: rows.map((r) => ({ filename: String(r.filename), checksum: String(r.checksum) })),
  };
  fs.mkdirSync(path.dirname(ledgerPath), { recursive: true });
  fs.writeFileSync(ledgerPath, `${JSON.stringify(payload, null, 2)}\n`, "utf8");
  return rows.length;
}

async function main() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.error("db:ledger:snapshot FAILED - DATABASE_URL is not set.");
    console.error("- The snapshot is generated FROM the canonical ledger; there is nothing to copy without it.");
    process.exit(1);
  }
  const ledgerPath = path.resolve(process.cwd(), "db/migrations/.ledger.json");
  const { default: pg } = await import("pg");
  const client = new pg.Client({
    connectionString: databaseUrl,
    ssl: databaseUrl.includes("sslmode=disable") ? false : { rejectUnauthorized: false },
  });
  await client.connect();
  try {
    const count = await writeLedgerSnapshot({ client, ledgerPath });
    console.log(`db:ledger:snapshot OK - wrote ${count} applied migrations to db/migrations/.ledger.json`);
    console.log("Commit the refreshed snapshot with the migration that caused it.");
  } finally {
    await client.end();
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error(`db:ledger:snapshot FAILED - ${error?.stack || String(error)}`);
    process.exit(1);
  });
}
